input.oldString:
function draw() {
  // Clear
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw player
  ctx.fillStyle = '#0a84ff';
  ctx.shadowColor = 'rgba(0,0,0,0.5)';
  ctx.shadowBlur = 6;
  drawRoundedRect(player.x, player.y, PLAYER_WIDTH, PLAYER_HEIGHT, 6);
  ctx.shadowColor = 'transparent';

  // Draw blocks with rounded corners and individual colors
  for (const b of blocks) {
    ctx.fillStyle = b.color || 'red';
    drawRoundedRect(b.x, b.y, b.size, b.size, 4);
  }

  // Draw score
  ctx.fillStyle = 'blue';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);

  // Game over overlay
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'white';
    ctx.font = '40px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 20);
    ctx.font = '30px Arial';
    ctx.fillText(`Final Score: ${score}`, canvas.width / 2, canvas.height / 2 + 30);
  }
}

input.newString:
function draw() {
  // Background gradient
  const bgGrad = ctx.createLinearGradient(0, 0, 0, canvas.height);
  bgGrad.addColorStop(0, '#e0f7ff');
  bgGrad.addColorStop(1, '#c2e0ff');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw player with rounded shape and shadow
  ctx.fillStyle = '#0a84ff';
  ctx.shadowColor = 'rgba(0,0,0,0.3)';
  ctx.shadowBlur = 6;
  drawRoundedRect(player.x, player.y, PLAYER_WIDTH, PLAYER_HEIGHT, 6);
  ctx.shadowColor = 'transparent';

  // Draw blocks with rounded corners and individual colors
  for (const b of blocks) {
    ctx.fillStyle = b.color || 'red';
    drawRoundedRect(b.x, b.y, b.size, b.size, 4);
  }

  // Draw score with stylized font
  ctx.fillStyle = '#333';
  ctx.font = 'bold 20px sans-serif';
  ctx.textAlign = 'left';
  ctx.fillText(`Score: ${score}`, 10, 30);

  // Game over overlay
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 40px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 20);
    ctx.font = '30px sans-serif';
    ctx.fillText(`Final Score: ${score}`, canvas.width / 2, canvas.height / 2 + 30);
  }
}

